import logging

import requests

from taf.hw.optical_switch.exceptions import OpticalSwitchConnectionError


class HttpClient:
    def __init__(self, user_name, password, host, port, timeout, base_url):
        self._user_name = user_name
        self._password = password
        self._host = host
        self._port = port
        self._timeout = timeout
        self._base_url = base_url
        self._session = requests.Session()
        self._session.verify = False
        self._logger = logging.getLogger(__name__)
        self._logger.setLevel(logging.DEBUG)

    def get(self, relative_url, params=None, **kwargs):
        url = self._base_url + relative_url
        response = self._make_requests_and_handle_conn_errors(
            "GET", url, params=params, **kwargs
        )
        return response

    def post(self, relative_url, data=None, **kwargs):
        url = self._base_url + relative_url
        response = self._make_requests_and_handle_conn_errors(
            "POST", url, data=data, **kwargs
        )
        return response

    def delete(self, relative_url, data, **kwargs):
        url = self._base_url + relative_url
        response = self._make_requests_and_handle_conn_errors(
            "DELETE", url, data=data, **kwargs
        )
        return response

    def _make_requests_and_handle_conn_errors(self, method, url, **kwargs):
        method_map = {
            "GET": self._session.get,
            "POST": self._session.post,
            "DELETE": self._session.delete,
        }
        try:
            logging.debug(f"Making {method} request to url {url}")
            response = method_map[method](
                url,
                timeout=self._timeout,
                auth=(self._user_name, self._password),
                **kwargs,
            )
            logging.debug(f"Response {response.status_code}: {response.text}")
            return response
        except requests.exceptions.RequestException as e:
            raise OpticalSwitchConnectionError(f"Error during request: {e}") from e

    def disconnect(self):
        self._session.close()
        self._session.keep_alive = False
